package com.nexushr.entity;
import jakarta.persistence.*; import java.time.*; import java.util.UUID; import java.math.BigDecimal;
@Entity @Table(name="performance_reviews") public class PerformanceReview { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) private Employee employee; @Column(nullable=false) private int reviewYear; @Column(precision=4,scale=2) private BigDecimal rating; @Column(length=4000) private String strengths; @Column(length=4000) private String improvementAreas; @Column(length=4000) private String managerFeedback; private LocalDate reviewDate; public UUID getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public int getReviewYear(){return reviewYear;} public void setReviewYear(int v){reviewYear=v;} public BigDecimal getRating(){return rating;} public void setRating(BigDecimal v){rating=v;} public String getStrengths(){return strengths;} public void setStrengths(String v){strengths=v;} public String getImprovementAreas(){return improvementAreas;} public void setImprovementAreas(String v){improvementAreas=v;} public String getManagerFeedback(){return managerFeedback;} public void setManagerFeedback(String v){managerFeedback=v;} public LocalDate getReviewDate(){return reviewDate;} public void setReviewDate(LocalDate v){reviewDate=v;} }
